const io=new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting&&(e.target.classList.add('v'),io.unobserve(e.target))),{threshold:.08});$$('.rv').forEach(e=>io.observe(e));
let cd=0;new IntersectionObserver((es,o)=>{if(es[0].isIntersecting&&!cd){cd=1;const t0=performance.now(),f=t=>{const p=Math.min((t-t0)/1800,1),k=1-Math.pow(1-p,3);$$('[data-n]').forEach(e=>e.textContent=Math.round(e.dataset.n*k)+(p>=1?e.dataset.x:''));p<1&&requestAnimationFrame(f)};requestAnimationFrame(f)}},{threshold:.3}).observe($('#stats'));
$$('.tabs').forEach(t=>$$('button',t).forEach((b,i)=>b.onclick=()=>{$$('button',t).forEach(x=>x.classList.toggle('on',x===b));$$('.pn[data-g="'+t.dataset.g+'"]').forEach((p,j)=>p.classList.toggle('on',j==i))}));
