const TY=EN?TY_EN:['Ph.D. en Ciencias de la Computación','Docente Titular de Inteligencia Artificial','Coordinador Académico · Doctorado Multidisciplinario','Investigador · Libro 2024 · 9 publicaciones','IA · Ciberseguridad · Software Libre'];let ti=0,tc=0,td=0;(function t(){const w=TY[ti];tc+=td?-1:1;$('#ty').textContent=w.slice(0,tc);let d=td?28:58;if(!td&&tc==w.length){td=1;d=1600}else if(td&&!tc){td=0;ti=(ti+1)%TY.length}setTimeout(t,d)})();
/* canvases */
const mxc=$('#mx'),mc=mxc.getContext('2d'),nc=$('#net'),nx=nc.getContext('2d');let W,H,cols,drops,P,mp={x:-999,y:-999};
function rs(){W=mxc.width=nc.width=innerWidth;H=mxc.height=nc.height=innerHeight;cols=Math.floor(W/18);drops=Array.from({length:cols},()=>Math.random()*H);P=Array.from({length:Math.min(70,W/18|0)},()=>({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.6,vy:(Math.random()-.5)*.6,r:Math.random()*1.8+.6}))}rs();addEventListener('resize',rs);addEventListener('mousemove',e=>mp={x:e.clientX,y:e.clientY});
(function d(){mc.fillStyle='rgba(5,13,28,.09)';mc.fillRect(0,0,W,H);mc.font='12px Space Grotesk,monospace';for(let i=0;i<cols;i++){mc.fillStyle=i%3?i%5?'rgba(81,162,218,.25)':'rgba(201,168,106,.35)':'rgba(0,217,255,.5)';mc.fillText(Math.random()>.5?'1':'0',i*18,drops[i]);if(drops[i]>H&&Math.random()>.975)drops[i]=0;drops[i]+=.7+Math.random()*1.6}
nx.clearRect(0,0,W,H);P.forEach((a,i)=>{for(let j=i+1;j<P.length;j++){const b=P[j],D=Math.hypot(a.x-b.x,a.y-b.y);if(D<160){nx.strokeStyle=`rgba(81,162,218,${.22*(1-D/160)})`;nx.lineWidth=.8;nx.beginPath();nx.moveTo(a.x,a.y);nx.lineTo(b.x,b.y);nx.stroke()}}
const m=Math.hypot(a.x-mp.x,a.y-mp.y);if(m<190){nx.strokeStyle=`rgba(0,217,255,${.5*(1-m/190)})`;nx.beginPath();nx.moveTo(a.x,a.y);nx.lineTo(mp.x,mp.y);nx.stroke();a.x+=(mp.x-a.x)*.003;a.y+=(mp.y-a.y)*.003}
a.x+=a.vx;a.y+=a.vy;(a.x<0||a.x>W)&&(a.vx*=-1);(a.y<0||a.y>H)&&(a.vy*=-1);nx.fillStyle=a.r>1.4?'#00D9FF':'#51A2DA';nx.shadowBlur=8;nx.shadowColor='#00D9FF';nx.beginPath();nx.arc(a.x,a.y,a.r,0,7);nx.fill();nx.shadowBlur=0});requestAnimationFrame(d)})();
function boom(e){for(let i=0;i<14;i++){const a=i/14*6.283,r=60+Math.random()*80,p=document.createElement('div');p.className='ex';p.style.cssText=`left:${e.clientX}px;top:${e.clientY}px;background:${['#00D9FF','#51A2DA','#C9A86A'][i%3]};--dx:${Math.cos(a)*r}px;--dy:${Math.sin(a)*r}px`;document.body.append(p);setTimeout(()=>p.remove(),900)}}
